  function drawDashboardChart(){const c=$('#financialChart');if(!c)return;const ctx=c.getContext('2d'),rect=c.getBoundingClientRect(),dpr=Math.min(2,devicePixelRatio||1);c.width=rect.width*dpr;c.height=rect.height*dpr;ctx.scale(dpr,dpr);const w=rect.width,h=rect.height,p={l:42,r:18,t:16,b:38},months=[];for(let i=5;i>=0;i--){const x=new Date();x.setDate(1);x.setMonth(x.getMonth()-i);months.push({key:x.toISOString().slice(0,7),label:new Intl.DateTimeFormat('ar-EG',{month:'short'}).format(x)})}const sales=months.map(m=>D().sales.filter(x=>x.status!=='returned'&&String(x.date).startsWith(m.key)).reduce((a,x)=>a+num(x.total),0)),purchases=months.map(m=>D().purchases.filter(x=>x.status!=='cancelled'&&String(x.date).startsWith(m.key)).reduce((a,x)=>a+num(x.total),0)),max=Math.max(1,...sales,...purchases)*1.12;ctx.clearRect(0,0,w,h);ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--line');ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--muted');ctx.font='11px Tahoma';ctx.textAlign='right';for(let i=0;i<=4;i++){const y=p.t+(h-p.t-p.b)*i/4;ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(w-p.r,y);ctx.stroke();ctx.fillText(Math.round(max*(1-i/4)).toLocaleString('ar-EG'),p.l-7,y+4)}ctx.textAlign='center';months.forEach((m,i)=>ctx.fillText(m.label,p.l+(w-p.l-p.r)*i/5,h-12));function line(vals,color){ctx.beginPath();vals.forEach((v,i)=>{const x=p.l+(w-p.l-p.r)*i/5,y=p.t+(h-p.t-p.b)*(1-v/max);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle=color;ctx.lineWidth=2.5;ctx.stroke();vals.forEach((v,i)=>{const x=p.l+(w-p.l-p.r)*i/5,y=p.t+(h-p.t-p.b)*(1-v/max);ctx.beginPath();ctx.arc(x,y,3.5,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()})}line(sales,getComputedStyle(document.documentElement).getPropertyValue('--primary'));line(purchases,getComputedStyle(document.documentElement).getPropertyValue('--amber'))}


